fields.source:
vars: {
  d2-config: {
    layout-engine: elk
  }
  red: "#c0392b"
  amber: "#c98a1e"
  blue: "#2f6fb3"
}

direction: down

user: User's browser {
  shape: person
}

cloudflare: Cloudflare edge {
  tunnel: cloudflared {
    shape: rectangle
  }
}

user -> cloudflare.tunnel: HTTPS / WSS\ntrader.smkabir.com

homelab: homelab-terraform repo {
  shape: rectangle
  style.stroke-dash: 3
  note: "Deploy manifests + image tags.\nThis repo (TraderBuddy) only builds\nand pushes images to GHCR."
}

gateway: Cilium Gateway API {
  gw: gateway/public\n(sectionName: https-wildcard) {
    shape: rectangle
  }
  route: HTTPRoute traderbuddy {
    shape: rectangle
  }
  gw -> route
}

cloudflare.tunnel -> gateway.gw: split-horizon on LAN,\ntunnel from WAN

traderbuddy: traderbuddy namespace {
  web: tb-web {
    tooltip: "Vite 6 + React 19 + TS\nlightweight-charts (OpenCharts fork)\nstatic image, path: /\nAlerts page: list, create, edit, renew, delete"
  }

  api: tb-api (BFF) {
    tooltip: "FastAPI, 2 replicas\nRoutes under /api and /ws\nOwns OIDC token exchange + refresh\nNever calls Zitadel per-request\nPolls a snapshot every 15 s for chart\nsymbols outside tb-stream's 30"
  }

  stream: tb-stream {
    style.stroke: "${red}"
    tooltip: "Singleton, strategy: Recreate\nONE Alpaca WS connection, account-wide\nLive charts only: top 30 symbols by open-chart interest\nSPOF by design — heartbeat monitored"
  }

  alerts: tb-alerts (CronJob) {
    tooltip: "Once a trading day, after the US close\n(30 16-20 * * 1-5, America/New_York)\nSIP 1-minute bars over REST — never ticks, never IEX\nCrossings use previous state, counting only\nbars after each alert's baseline"
  }

  ingest: tb-ingest {
    tooltip: "CronJobs, one tb-ingest image:\nsymbols · bars-retention · macro (FRED, CAPE)\nportfolio-snapshots and digest, 17:00 America/New_York"
  }

  image_note: same tb-api image,\ndifferent command per workload {
    shape: text
    style.italic: true
    style.font-size: 13
  }
}

gateway.route -> traderbuddy.web: PathPrefix /
gateway.route -> traderbuddy.api: PathPrefix /api, /ws

platform: platform namespace {
  pg: pg-main (CNPG) {
    shape: cylinder
    tooltip: "3 instances, Postgres WAL replication\nDatabase per app: traderbuddy, zitadel\nDurable state lives HERE, never in Valkey"
  }

  pooler: PgBouncer Pooler {
    shape: queue
    tooltip: "poolMode: transaction\nFor apps only — NOT for Zitadel"
  }

  valkey: Valkey {
    shape: cylinder
    style.stroke: "${amber}"
    tooltip: "Single instance, strategy: Recreate\nPub/sub: ticks and 1-min bars per symbol, alerts per user\nInterest sorted set + rate-limit buckets\nNo durable state — not a queue, not sessions"
  }

  zitadel: Zitadel {
    tooltip: "OIDC @ auth.smkabir.com\n1 replica, stateless\nBFF pattern: touched only at login\n+ token refresh, never per-request"
  }

  pooler -> pg: transaction pooling
  zitadel -> pg: direct connection\n(bypasses pooler — session features\nbreak under transaction pooling)
}

traderbuddy.api -> platform.pooler: asyncpg pool\n(sessions, watchlists, alerts, users)
traderbuddy.api -> platform.valkey: rate limiter (Valkey-backed,\nnever per-process)
traderbuddy.api -> platform.zitadel: login code exchange +\ntoken refresh ONLY
traderbuddy.alerts -> platform.pooler: alerts, alert_events
traderbuddy.ingest -> platform.pooler
traderbuddy.stream -> platform.valkey: "publish ticks:<symbol>"
traderbuddy.alerts -> platform.valkey: "publish alerts:<user_id>\n(AlertTriggered)"
traderbuddy.api -> platform.valkey: "subscribe ticks:<symbol>, alerts:<user_id>\n(fan out over /ws, per user)"

providers: External providers {
  alpaca: Alpaca (WS + REST) {
    tooltip: "Free plan: ONE WS connection, 30 symbols,\nreal-time from IEX only; REST 200 calls/min;\nSIP data allowed once it's 15 minutes old"
  }
  finnhub: Finnhub {
    tooltip: "60 req/min, account-wide\nRedis token bucket + caching"
  }
  fred: FRED (macro series)
  slack: Slack (bot token, DMs) {
    tooltip: "Each user's own DM channel only.\nNever a webhook or a shared channel —\nalerts and holdings are private."
  }
}

traderbuddy.stream -> providers.alpaca: single upstream WS\n(30 symbols max)
traderbuddy.api -> providers.alpaca: REST (bars, symbols,\nsnapshots beyond the 30)
traderbuddy.api -> providers.finnhub: REST, rate-limited
traderbuddy.alerts -> providers.alpaca: "REST: calendar + SIP 1-min bars\nafter the close"
traderbuddy.ingest -> providers.fred: macro ingestion
traderbuddy.alerts -> providers.slack: one DM per user\n(the day's triggers)
traderbuddy.ingest -> providers.slack: daily digest DM

homelab -> platform: deploy manifests\n(Argo CD applies)
homelab -> traderbuddy: image tags\n(tb-api / tb-web from GHCR)

user.style.fill: "${blue}"

#
# The component diagram (architecture.d2) shows these services exist. This one shows
# the two data paths, because they are deliberately separate: live ticks are for eyes
# (a 30-symbol WebSocket budget, a singleton upstream, Cloudflare idling quiet
# sockets), and alerts never touch them (REST SIP bars, once, after the close).

vars: {
  d2-config: {
    layout-engine: elk
  }
  red: "#c0392b"
  amber: "#c98a1e"
}

direction: right

# Live charts — market hours, at most 30 symbols streamed

browsers: "Browsers\n(N users)" {
  style.multiple: true
}

api_ws: "tb-api /ws handlers\n(N connections, per browser)" {
  tooltip: "Session-authenticated via BFF cookie —\nno token in the WS query string.\nFan-out is filtered to each connection's\nown interest set."
}

interest: "Valkey sorted set\ninterest:symbols" {
  shape: cylinder
  style.stroke: "${amber}"
  tooltip: "ZADD with the current time as score, for every\nsymbol a browser reports. tb-stream trims\nentries older than 90 s."
}

alpaca_ws: Alpaca WS (IEX) {
  tooltip: "Free plan: ONE concurrent connection\nand 30 symbols, per account — not per user."
}

stream: tb-stream {
  style.stroke: "${red}"
  style.stroke-width: 3
  tooltip: "replicas: 1, strategy: Recreate (not RollingUpdate).\nA rolling update briefly runs two pods, both dial\nAlpaca, and one connection gets rejected/evicted.\nEvery 10 s: top 30 by interest, 60 s hysteresis,\nthen subscribe/unsubscribe quotes and bars."
}

live_set: "Valkey\nstream:subscribed\nstream:heartbeat" {
  shape: cylinder
  style.stroke: "${amber}"
  tooltip: "The live set, rewritten with a 30 s expiry,\nand the heartbeat. A stale heartbeat is how\nyou find out the singleton died."
}

pubsub: "Valkey pub/sub\nticks, bars1m per symbol\nalerts per user" {
  shape: cylinder
  style.stroke: "${amber}"
  tooltip: "No durable state. If nothing is subscribed\nwhen a message publishes, it is gone —\na live feed, not a queue."
}

alpaca_rest: Alpaca REST {
  tooltip: "Free plan: 200 calls/min, no symbol cap.\nOne multi-symbol request covers many symbols.\nSIP data is allowed once it's 15 minutes old."
}

browsers -> api_ws: "interest frame\n(on change + every 30 s)"
api_ws -> interest: ZADD
interest -> stream: top 30,\nevery 10 s
alpaca_ws -> stream: single upstream WS,\naccount-wide
stream -> live_set: live set + heartbeat
stream -> pubsub: PUBLISH ticks\nand 1-min bars
pubsub -> api_ws: SUBSCRIBE, fan out\nper connection
live_set -> api_ws: "not in the live set →\nSymbolDelayed"
api_ws -> alpaca_rest: "snapshot every 15 s for\ndelayed symbols (single-flight)"
api_ws -> browsers: "WS push +\napplication-level ping ~30s" {
  tooltip: "Cloudflare idles quiet WebSockets.\nA silently dead socket looks identical to\na quiet market — the worst failure mode here.\nServer pings, client pongs, to keep it honest."
}

# Alerts — once a trading day, after the close; never reads the tick stream

alerts: "tb-alerts\n(CronJob, after the close)" {
  tooltip: "30 16-20 * * 1-5, America/New_York.\nThe 16:30 run evaluates; later runs only\nretry undelivered DMs."
}

pg: "Postgres\nalerts, alert_events" {
  shape: cylinder
  tooltip: "alert_events is unique per (alert, trading date),\nso a rerun can never fire twice.\nOnly bars after an alert's baseline count."
}

slack: "Slack\n(DMs only)" {
  shape: cloud
  tooltip: "Alerts and digests go to each user's own DM —\nnever a webhook or a shared channel."
}

alerts -> alpaca_rest: "calendar + the session's\nSIP 1-min bars"
alerts -> pg: crossings vs\nprevious state
alerts -> slack: "one DM per user\n(the day's triggers)"
alerts -> pubsub: "PUBLISH AlertTriggered\n(toast for users online)"

monitor: "Heartbeat monitor" {
  style.stroke-dash: 3
}

live_set -> monitor: poll for staleness
monitor -> slack: "alert: tb-stream is down" {
  style.stroke: "${red}"
}
